const tabId = 2017691801;
await tool.navigate({ tabId, url: "https://www.lulus.com/search?q=emerald+green+dress" });

await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 15000 });
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 3000 });

const pageData = await browserjs(tabId, () => {
  // Let's find products on Lulus
  const items = Array.from(document.querySelectorAll('a[href*="/products/"]'));
  const products = [];
  const seen = new Set();

  for (const item of items) {
    const href = item.href;
    if (seen.has(href) || !href.includes('.html')) continue;
    seen.add(href);

    const card = item.closest('[class*="product"], [class*="item"]') || item;
    const title = card.querySelector('[class*="name"], [class*="title"]')?.innerText?.trim() || item.innerText?.trim();
    const price = card.querySelector('[class*="price"]')?.innerText?.trim();
    const rating = card.querySelector('[class*="rating"], [class*="review"], [aria-label*="star"], [aria-label*="rating"]')?.getAttribute('aria-label') || card.querySelector('[class*="stars"]')?.innerText?.trim();

    if (title && title.length > 5 && !title.toLowerCase().includes('view')) {
      products.push({ title, price, rating, href });
    }
  }

  // Also check size filter options
  const sizeOptions = Array.from(document.querySelectorAll('label, button, a'))
    .filter(el => /^(12|L|XL)$/i.test(el.innerText?.trim()))
    .map(el => ({ text: el.innerText.trim(), tag: el.tagName, className: el.className }));

  return { count: products.length, products: products.slice(0, 10), sizeOptions };
});

console.log(JSON.stringify(pageData, null, 2));

