});

// Let's inspect the products and their links
const asosProducts = await browserjs(tabId, () => {
  const articles = Array.from(document.querySelectorAll('article, a[href*="/prd/"]'));
  const list = [];
  const seen = new Set();

  for (const el of articles) {
    const link = el.tagName === 'A' ? el : el.querySelector('a[href*="/prd/"]');
    if (!link) continue;
    const href = link.href;
    if (seen.has(href)) continue;
    seen.add(href);

