const productInfo = await browserjs(tabId, () => {
  // Let's find product details text
  const sections = Array.from(document.querySelectorAll('section, div'))
    .filter(el => el.innerText && (el.innerText.includes('Product Details') || el.innerText.includes('ABOUT ME') || el.innerText.includes('LOOK AFTER ME') || el.innerText.includes('SIZE & FIT')));

  // Also get images
  const imgs = Array.from(document.querySelectorAll('img'))
    .filter(img => img.src && img.src.includes('images.asos-media.com/products/'))
    .map(img => ({ alt: img.alt, src: img.src }));

  // Shipping & return snippet
  const deliverySnippet = Array.from(document.querySelectorAll('p, div, span, a'))
    .filter(el => el.innerText && (el.innerText.includes('Delivery') || el.innerText.includes('Returns')))
    .map(el => el.innerText.trim())
    .filter(t => t.length > 10 && t.length < 200);

  return {
    sections: sections.map(s => s.innerText.slice(0, 300)).slice(0, 5),
    imgs: imgs.slice(0, 6),
    deliverySnippet: deliverySnippet.slice(0, 8),
    bodySnippet: document.body.innerText.slice(1000, 3000)
  };
});

