const tabId = 2017691803;

// Let's check Love Sunshine Emerald Green Shirred High Neck Midaxi Dress on Boohoo
await tool.navigate({ tabId, url: "https://www.boohoo.com/product/love-sunshine-emerald-green-shirred-high-neck-midaxi-dress_p-2f961e74-50be-432b-b279-05f38d227d1b?colour=Emerald" });

await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 15000 });
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 3000 });

const details = await browserjs(tabId, () => {
  const title = document.querySelector('h1')?.innerText.trim() || document.title;
  const price = document.querySelector('[data-test-id="pdp-price"], [class*="price"]')?.innerText.trim();
  const sizes = Array.from(document.querySelectorAll('button, div'))
    .filter(el => /^(8|10|12|14|16|S|M|L|XL)$/i.test(el.innerText?.trim()) && el.getAttribute('data-test-id')?.includes('size'))
    .map(el => ({ text: el.innerText.trim(), disabled: el.className.includes('disabled') || el.disabled }));

  // Also check all buttons with size
  const allButtons = Array.from(document.querySelectorAll('button'))
    .map(b => ({
      text: b.innerText.trim(),
      disabled: b.disabled || b.getAttribute('aria-disabled') === 'true' || b.className.includes('disabled') || b.className.includes('opacity-50')
    }))
    .filter(b => /^(8|10|12|14|16|S|M|L|XL)$/i.test(b.text));

  return {
    title,
    price,
    sizes,
    allButtons,
    bodySnippet: document.body.innerText.slice(0, 1500)
  };
});

console.log("Boohoo Dress 1:", JSON.stringify(details, null, 2));

