        text: b.innerText.trim(),
        disabled: b.disabled || b.getAttribute('aria-disabled') === 'true' || b.className.includes('disabled') || b.className.includes('opacity-50')
      }))
      .filter(b => /^(8|10|12|14|16|18|20)$/.test(b.text));

    const size12 = buttons.find(b => b.text === '12');

    return { title, price, size12, buttons, url: window.location.href };
  });

  results.push(info);
}

