  "https://www.karenmillen.com/product/karen-millen-compact-stretch-strappy-asymmetric-hem-maxi-dress_bkk31387?colour=emerald"
];

const results = [];
for (const url of testUrls) {
  await tool.navigate({ tabId, url });
